import random
from feal import f_function

def const_diff(d):
    vals=set()
    for _ in range(100):
        x=random.randrange(1<<32)
        vals.add(f_function(x)^f_function(x^d))
        if len(vals)>1: return None
    return vals.pop()

specials={}
for mask in range(1,16):
    d=0
    for i in range(4):
        if (mask>>i)&1: d |= 0x80<<(8*i)
    c=const_diff(d)
    if c is not None:
        specials[d]=c
print(len(specials))
for d,c in specials.items():
    print(f"{d:08x} -> {c:08x}")
